using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using System.Text.RegularExpressions;
using Paylink;
using Paylink.Internal;
using Paylink.Signing;
using Xunit;

namespace Paylink.Tests
{
    /// <summary>
    /// Cross-language signature parity. Reuses the JS/Python golden-signature fixtures
    /// (generated by PHP with the same primitive the server uses). If these pass, the .NET
    /// SDK builds byte-identical signatures to the PHP server and the other SDKs.
    /// </summary>
    public sealed class GoldenSignatureTests
    {
        private static readonly JsonElement Fixtures = LoadFixtures();

        private static readonly IReadOnlyDictionary<string, EndpointSpec> Specs =
            new Dictionary<string, EndpointSpec>
            {
                { "INVOICE_CREATE", FieldOrders.InvoiceCreate },
                { "PAYMENT_VOID", FieldOrders.PaymentVoid },
                { "PAYMENT_REFUND", FieldOrders.PaymentRefund },
                { "PAYMENT_SETTLE", FieldOrders.PaymentSettle },
                { "PAYMENT_REVERSE_AUTHORIZATION", FieldOrders.PaymentReverseAuthorization },
                { "PAYMENT_CHECK_STATUS", FieldOrders.PaymentCheckStatus },
                { "VCC_CHARGE", FieldOrders.VccCharge },
                { "CARD_TOKENIZE", FieldOrders.CardTokenize },
                { "CARD_CHARGE", FieldOrders.CardCharge },
                { "CARD_REVOKE", FieldOrders.CardRevoke },
                { "RECURRING_CREATE", FieldOrders.RecurringCreate },
            };

        [Fact]
        public void PrimitiveSignatureMatchesEveryCase()
        {
            foreach (var testCase in Fixtures.GetProperty("cases").EnumerateArray())
            {
                var values = new List<string>();
                foreach (var value in testCase.GetProperty("values").EnumerateArray())
                {
                    values.Add(value.GetString()!);
                }

                Assert.Equal(testCase.GetProperty("expected").GetString(), Signature.Build(values, HashToken(testCase)));
            }
        }

        [Fact]
        public void StructuredBodySignatureMatches()
        {
            foreach (var testCase in Fixtures.GetProperty("cases").EnumerateArray())
            {
                var endpoint = testCase.GetProperty("endpoint").GetString()!;
                if (!Specs.TryGetValue(endpoint, out var spec))
                {
                    continue;
                }

                var input = ToSnakeInput(testCase.GetProperty("input"));
                var body = SignedBody.Build(spec, input, "pub_token", HashToken(testCase));

                Assert.Equal(testCase.GetProperty("expected").GetString(), body["signature"]);
                Assert.Equal("pub_token", body["token"]);
            }
        }

        [Fact]
        public void MandateActionSignsTheUid()
        {
            var testCase = FindCase("RECURRING_MANDATE_ACTION");
            var uid = testCase.GetProperty("input").GetProperty("mandateId").GetString()!;

            Assert.Equal(testCase.GetProperty("expected").GetString(), Signature.Build(new[] { uid }, HashToken(testCase)));
        }

        [Fact]
        public void WebhookSignatureVerifies()
        {
            foreach (var testCase in Fixtures.GetProperty("cases").EnumerateArray())
            {
                if (testCase.GetProperty("endpoint").GetString() != "WEBHOOK")
                {
                    continue;
                }

                var hashToken = HashToken(testCase);
                var client = new PaylinkClient("pub", hashToken);

                var payload = (Dictionary<string, object?>)Json.ToClr(testCase.GetProperty("input"))!;
                payload["signature"] = testCase.GetProperty("expected").GetString();
                var json = JsonSerializer.Serialize(payload);

                Assert.True(client.Webhooks.IsValid(json, hashToken));

                payload["signature"] = "AAAA";
                Assert.False(client.Webhooks.IsValid(JsonSerializer.Serialize(payload), hashToken));
            }
        }

        private static IReadOnlyDictionary<string, object?> ToSnakeInput(JsonElement input)
        {
            var result = new Dictionary<string, object?>();
            foreach (var property in input.EnumerateObject())
            {
                result[CamelToSnake(property.Name)] = ToInputValue(property.Value);
            }

            return result;
        }

        private static object? ToInputValue(JsonElement value)
        {
            switch (value.ValueKind)
            {
                case JsonValueKind.String:
                    return value.GetString();
                case JsonValueKind.Number:
                    return value.TryGetInt64(out var integer) ? (object)integer : value.GetDouble();
                case JsonValueKind.True:
                    return true;
                case JsonValueKind.False:
                    return false;
                default:
                    return null;
            }
        }

        private static string CamelToSnake(string key)
        {
            return Regex.Replace(key, "(?<!^)([A-Z])", "_$1").ToLowerInvariant();
        }

        private static string HashToken(JsonElement testCase)
        {
            return testCase.TryGetProperty("hashToken", out var value)
                ? value.GetString()!
                : Fixtures.GetProperty("hashToken").GetString()!;
        }

        private static JsonElement FindCase(string endpoint)
        {
            foreach (var testCase in Fixtures.GetProperty("cases").EnumerateArray())
            {
                if (testCase.GetProperty("endpoint").GetString() == endpoint)
                {
                    return testCase;
                }
            }

            throw new InvalidOperationException("Missing fixture: " + endpoint);
        }

        private static JsonElement LoadFixtures()
        {
            var path = Path.Combine(AppContext.BaseDirectory, "golden-signatures.json");
            using (var document = JsonDocument.Parse(File.ReadAllText(path)))
            {
                return document.RootElement.Clone();
            }
        }
    }
}
